 const activeTab=matchTabs.find(t=>t.id===activeTabId)||matchTabs[0];const isMatchOwner=!!activeTab&&(activeTab.ownerId?activeTab.ownerId===(authUser?.id||'local'):(!authUser||cloudMatchOwner));const isMatchGM=cloudMatchRole==='gm';const canEditActiveStats=!!active&&(isMatchGM||(isMatchOwner&&!!active.dummy));const canViewActiveStats=!!active&&(isMatchGM||(isMatchOwner&&!!active.dummy)||settingsDraft.viewAllStats===true||(settingsDraft.viewOpponentStats===true&&(myTeam==='blue'||myTeam==='red')&&active.team!==myTeam)||(active.team===myTeam)||controlledPlayerId===active.id);const canViewShadowStats=!!active&&(!shadowMode||!!activeTab?.shadowPlayers?.includes(active.id));const matchPermissions=activeTab?.permissions??{playersMoveOwn:true,captainBlue:false,captainRed:false};const isCaptainBlue=!!authUser?.id&&settingsDraft.captainBlueUserId===authUser.id;const isCaptainRed=!!authUser?.id&&settingsDraft.captainRedUserId===authUser.id;const canMovePlayer=(p:Player)=>p.dummy?(isMatchOwner||myTeam===p.team):isMatchGM||(myTeam===p.team&&((isCaptainBlue&&p.team==='blue')||(isCaptainRed&&p.team==='red')||(matchPermissions.playersMoveOwn&&controlledPlayerId===p.id)));const canAssignPosition=(p:Player)=>p.dummy?(isMatchOwner||myTeam===p.team):isMatchGM||(myTeam===p.team&&((isCaptainBlue&&p.team==='blue')||(isCaptainRed&&p.team==='red')));const visiblePlayers=players.filter(p=>(isMatchOwner?p.dummy||!p.dummy:myTeam==='observer'||p.team===myTeam)&&(!playerSearch.trim()||[p.name,p.role,String(p.number),String(p.id)].some(v=>v.toLowerCase().includes(playerSearch.trim().toLowerCase()))));
