 const canViewCardStats=!!active&&(isMatchGM||(isMatchOwner&&!!active.dummy)||active.team===myTeam||controlledPlayerId===active.id);function playerStats(p:Player):Record<StatKey,number>{const defaults:Record<StatKey,number>={accuracy:30,finishing:30,passing:30,heading:30,dribbling:30,control:30,tackling:30,defense:30,strength:30,jump:30,stamina:30,speed:30,reading:30,vision:30};return{...defaults,...p.stats}}
 function statTotal(p:Player){return Object.values(playerStats(p)).reduce((a,b)=>a+b,0)}
 function updateStat(key:StatKey,value:number){if(!(isMatchGM||(isMatchOwner&&!!active?.dummy))){flash('Редактировать характеристики может только ГМ; создатель может редактировать болванчиков');return}if(!active)return;const next=clamp(value,30,(active.weapons||[]).includes(key)?100:70);const stats=playerStats(active);const total=statTotal(active)-stats[key]+next;if(total>900){flash('Лимит характеристик — 900 очков');return}setPlayers(ps=>ps.map(p=>p.id===active.id?{...p,stats:{...stats,[key]:next},rating:Math.round((statTotal(p)-stats[key]+next)/14)}:p))}
 function toggleWeapon(key:StatKey){if(!(isMatchGM||(isMatchOwner&&!!active?.dummy))){flash('Реальных игроков может редактировать только ГМ; создатель может редактировать болванчиков');return}if(!active)return;const weapons=active.weapons||[];if(weapons.includes(key)){const stats=playerStats(active);const reduced={...stats,[key]:clamp(stats[key]-20,30,70)};setPlayers(ps=>ps.map(p=>p.id===active.id?{...p,weapons:weapons.filter(k=>k!==key),stats:reduced,rating:Math.round(Object.values(reduced).reduce((a,b)=>a+b,0)/14)}:p));return}if(weapons.length>=2){flash('Можно выбрать ровно два оружия');return}const stats=playerStats(active);const upgraded={...stats,[key]:clamp(stats[key]+20,30,100)};if(statTotal(active)-stats[key]+upgraded[key]>900){flash('Лимит характеристик — 900 очков');return}setPlayers(ps=>ps.map(p=>p.id===active.id?{...p,weapons:[...weapons,key],stats:upgraded}:p));flash('Оружие выбрано: +20 к характеристике')}
