 function svgPoint(svg:SVGSVGElement,clientX:number,clientY:number):Point{const matrix=svg.getScreenCTM();if(matrix){const point=svg.createSVGPoint();point.x=clientX;point.y=clientY;const local=point.matrixTransform(matrix.inverse());return{x:local.x,y:local.y}}const r=svg.getBoundingClientRect();return{x:(clientX-r.left)/r.width*100,y:(clientY-r.top)/r.height*100}}
 function pitchClick(e:React.MouseEvent<SVGSVGElement>){if(mode==='camera')return;const p0=svgPoint(e.currentTarget,e.clientX,e.clientY);const p={x:clamp(p0.x,2,98),y:clamp(p0.y,2,98)};if(mode==='pass'||mode==='move'){if(!pathStart)setPathStart(p);else{setPaths(a=>[...a,[pathStart,p]]);setPathStart(null)}}else if(mode==='select'){if(isMatchOwner||isMatchGM){setBall(p)}else flash('Мяч может двигать только создатель матча или ГМ')}}
